void helper_assert_stack_peek(DArrayStack *stack, int expected_value) {
    int success = 0;
    TEST_ASSERT_NOT_NULL(stack);
    int top_value = peek(stack, &success);
    TEST_ASSERT_EQUAL_INT(1, success);
    TEST_ASSERT_EQUAL_INT(expected_value, top_value);
}

// Asserts that popping from a stack returns the expected value and updates stack correctly
void helper_assert_stack_pop(DArrayStack *stack, int expected_value) {
    int success = 0;
    int popped_value = pop(stack, &success);
    TEST_ASSERT_EQUAL_INT(1, success);
    TEST_ASSERT_EQUAL_INT(expected_value, popped_value);
}

// Asserts that the string representation of a stack matches the expected string
void helper_assert_stack_to_string(DArrayStack *stack, const char *expected_string) {
    int buffer_size = 256;
    char *buffer = malloc(buffer_size * sizeof(char));
    int result = stack_to_string(stack, buffer, buffer_size);
    TEST_ASSERT_NOT_EQUAL_INT(-1, result);
    TEST_ASSERT_EQUAL_STRING(expected_string, buffer);
    free(buffer);
}

